Ghost:
```js
function fly(cardId, from, to, {faceDown=false}={}) {
  if (!from || !to) return;
  const el = document.createElement('div');
  el.className='fx-ghost';
  el.innerHTML = UI.cardHTML({uid:'fx',cardId},{faceDown,uidAttr:false});
  el.style.left=from.left+'px'; top... width=from.width; height=from.height;
  document.body.appendChild(el);
  const dx=to.left-from.left, dy=to.top-from.top;
  const sx=to.width/from.width, sy=to.height/from.height;
  el.animate([
    {transform:'translate(0,0) scale(1)', opacity:1},
    {transform:`translate(${dx*0.5}px,${dy*0.5-30}px) scale(${(1+sx)/2},${(1+sy)/2})`, opacity:1, offset:0.6},
    {transform:`translate(${dx}px,${dy}px) scale(${sx},${sy})`, opacity:.9}
  ], {duration:480, easing:'cubic-bezier(.2,.8,.2,1)'}).onfinish=()=>el.remove();
}
```
