function floatText(owner, text, cls) {
  const target = document.querySelector(`[data-lp-owner="${owner}"]`) || ...
  const r = target.getBoundingClientRect();
  const el = document.createElement('div'); el.className='float-text '+cls; el.textContent=text;
  el.style.left = r.left + r.width/2; top = r.top;
  document.body.appendChild(el); setTimeout(remove, 1000);
}
